import assert from 'node:assert/strict';import{createRequire}from'node:module';import{resolve}from'node:path';import{pathToFileURL}from'node:url';import{mkdir,writeFile,readFile}from'node:fs/promises';import{createHash}from'node:crypto';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');const evidence=resolve('../../outputs/verification-v35-batter-camera-side-v1');await mkdir(evidence);
const original=await readFile('../../outputs/ばせぼーるlv34_TBD_vs_LAD_UI復元版.html','utf8');const before='const base={eye:{x:-.4*s,y:Math.max(1.15,observed.batter.height*.77),z:-.95},yaw:Math.atan2(.4*s,19.4),pitch:.08,f:400,cx:300,cy:110,labelMetres:.55};';assert.equal(original.split(before).length,2);const changed=original.replace(before,before.replace('x:-.4*s','x:.4*s').replace('Math.atan2(.4*s,19.4)','Math.atan2(-.4*s,19.4)'));
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const observations={};for(const mode of ['originalV34','candidateCameraOnly']){
  const page=await browser.newPage({viewport:{width:1200,height:860}});if(mode==='originalV34')await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv34_TBD_vs_LAD_UI復元版.html')).href);else await page.setContent(changed);await page.evaluate(()=>document.fonts.ready);
  observations[mode]=await page.evaluate(()=>{
   const a=document.getElementById('auto-overhead');a.checked=false;a.dispatchEvent(new Event('change'));document.querySelector('[data-camera="batter"]').click();document.getElementById('managed-team').value='0';document.getElementById('batting-choice').value='take';
   const out={};for(let i=0;i<10;i++){
    document.getElementById('next-pitch').click();window.liveMatchPlayback.stop();let s=window.liveMatchPlayback.inspect();if(s.error)throw Error(s.error);
    const side=s.lastResult.play.diagnostics.battingSide;if(!out[side]){
     const indices=s.lastResult.frames.map((f,index)=>({f,index})).filter(v=>v.f.phase==='pitch');window.liveMatchPlayback.seekFrame(indices[Math.floor(indices.length/2)].index);s=window.liveMatchPlayback.inspect();
     const actor=s.currentFrame.actors.find(v=>v.playerId===s.currentFrame.batterPlayerId);out[side]={side,batter:actor,sourceFrame:s.currentFrame,eye:s.rendered.cameraEye,yaw:s.rendered.cameraYaw,pitch:s.rendered.cameraPitch,
      camera:s.rendered.camera,zoneCorners:s.rendered.zoneCorners,visibleCorners:s.rendered.zoneCorners.filter(p=>p&&p.x>=0&&p.x<=600&&p.y>=0&&p.y<=432).length,recordIndex:s.selectedPitch,frameIndex:s.frameIndex};
    }if(out.L&&out.R)break;
   }return out;
  });
  for(const side of ['L','R']){const o=observations[mode][side];assert(o,'both actual batting sides required');await page.evaluate(o=>window.liveMatchPlayback.seekPitch(o.recordIndex,o.frameIndex),o);await page.locator('.broadcast').screenshot({path:resolve(evidence,mode+'-'+side+'.png')});}
  await page.close();
 }
 for(const side of ['L','R']){const a=observations.originalV34[side],b=observations.candidateCameraOnly[side];assert(a.batter.position.x*a.eye.x<0);assert(b.batter.position.x*b.eye.x>0);assert.deepEqual(a.sourceFrame,b.sourceFrame);assert.equal(a.eye.z,b.eye.z);assert.equal(a.eye.y,b.eye.y);assert.equal(a.pitch,b.pitch);assert.equal(a.visibleCorners,b.visibleCorners);for(let i=0;i<4;i++){assert(Math.abs(a.zoneCorners[i].x+b.zoneCorners[[1,0,3,2][i]].x-600)<1e-8);assert(Math.abs(a.zoneCorners[i].y-b.zoneCorners[[1,0,3,2][i]].y)<1e-8);}}
 await writeFile(resolve(evidence,'camera-side.json'),JSON.stringify({status:'PASS_CAMERA_OPPOSITE_SIDE_REPRODUCED',originalSha256:createHash('sha256').update(original).digest('hex'),candidate:'in-memory camera x/yaw sign only; no saved HTML or Source edit',sourceFramesUnchanged:true,observations},null,2)+'\n');
 console.log(JSON.stringify({status:'PASS_CAMERA_OPPOSITE_SIDE_REPRODUCED',comparison:Object.fromEntries(['L','R'].map(side=>[side,{sourceBodyX:observations.originalV34[side].batter.position.x,oldEyeX:observations.originalV34[side].eye.x,candidateEyeX:observations.candidateCameraOnly[side].eye.x,visibleCorners:observations.originalV34[side].visibleCorners}])),sourceFramesUnchanged:true,evidence},null,2));
}finally{await browser.close();}
